import React from 'react';
import { Card } from 'react-bootstrap';
import 'bootstrap-icons/font/bootstrap-icons.css';

const StatsCard = ({ title, value, icon, color, format, trend }) => {
  const getIcon = () => {
    switch (icon) {
      case 'currency-dollar':
        return <BiDollar size={24} />;
      case 'cart':
        return <BiCart size={24} />;
      case 'box':
        return <BiBox size={24} />;
      case 'people':
        return <BiPeople size={24} />;
      case 'trending-up':
        return <span className="text-success">↗</span>;
      case 'trending-down':
        return <span className="text-danger">↘</span>;
      default:
        return <BiBox size={24} />;
    }
  };

  const formatValue = (val) => {
    if (format === 'currency') {
      return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD'
      }).format(val);
    }
    return val.toLocaleString();
  };

  const getColorClass = () => {
    switch (color) {
      case 'primary':
        return 'bg-primary';
      case 'success':
        return 'bg-success';
      case 'warning':
        return 'bg-warning';
      case 'danger':
        return 'bg-danger';
      case 'info':
        return 'bg-info';
      default:
        return 'bg-primary';
    }
  };

  return (
    <Card className="text-white mb-3">
      <Card.Body className={getColorClass()}>
        <div className="d-flex justify-content-between align-items-center">
          <div>
            <h6 className="card-title mb-1">{title}</h6>
            <h3 className="mb-0">{formatValue(value)}</h3>
            {trend && (
              <small className="d-flex align-items-center">
                {trend > 0 ? (
                  <span className="text-success me-1">↗</span>
                ) : (
                  <span className="text-danger me-1">↘</span>
                )}
                {Math.abs(trend)}% from last month
              </small>
            )}
          </div>
          <div className="opacity-75">
            {getIcon()}
          </div>
        </div>
      </Card.Body>
    </Card>
  );
};

export default StatsCard;
